#!/usr/bin/env python3
"""Read the native transcripts of the headless probe cases: python3 read_probes.py results-f.tsv [results-c.tsv ...].

Method follows the reference extractor in evidence/receipts/claude-model-effort-probes-20260929.json (extract_all.py): each
assistant message id is counted once (a message spans several rows); the recorded `effort` field is the client's own per-message
record. Beyond the reference it also reports the Workflow / Agent tool calls and whether each returned a result, the session's
own result text, and a first-user-message snippet for every child transcript so a child is identified by its prompt token.
"""
import collections
import glob
import json
import os
import sys

BASE = os.path.dirname(os.path.abspath(__file__))
PROJECTS = os.path.expanduser("~/.claude/projects")


def load_result(name):
    path = os.path.join(BASE, "out-%s.json" % name)
    try:
        data = json.load(open(path))
    except Exception as exc:  # noqa: BLE001
        return {"error": "unreadable out json: %s" % exc}
    if isinstance(data, list):
        data = next((e for e in reversed(data) if isinstance(e, dict) and e.get("type") == "result"), {})
    return data if isinstance(data, dict) else {}


def summarize(path):
    seen, versions, reminder, tool_use, tool_result = {}, set(), 0, collections.Counter(), collections.Counter()
    first_user = None
    for line in open(path, errors="replace"):
        try:
            row = json.loads(line)
        except ValueError:
            continue
        if row.get("version"):
            versions.add(row["version"])
        message = row.get("message") or {}
        role = message.get("role")
        if role == "assistant" and message.get("model") and message["model"] != "<synthetic>":
            seen.setdefault(message.get("id"), (message["model"], str(row.get("effort"))))
        if "Ultracode is on: optimize" in line:
            reminder += 1
        content = message.get("content")
        if isinstance(content, list):
            for block in content:
                if not isinstance(block, dict):
                    continue
                if block.get("type") == "tool_use":
                    tool_use[block.get("name")] += 1
                if block.get("type") == "tool_result":
                    tool_result["result"] += 1
        if role == "user" and first_user is None:
            if isinstance(content, str):
                first_user = content
            elif isinstance(content, list):
                first_user = " ".join(b.get("text", "") for b in content if isinstance(b, dict) and b.get("type") == "text")
    return {
        "messages": len(seen),
        "models": dict(collections.Counter(v[0] for v in seen.values())),
        "efforts": dict(collections.Counter(v[1] for v in seen.values())),
        "versions": sorted(versions),
        "reminder_lines": reminder,
        "tool_use": dict(tool_use),
        "tool_results": tool_result["result"],
        "first_user": (first_user or "")[:70].replace("\n", " "),
    }


def main(files):
    for results in files:
        for entry in open(results):
            name, case_dir = entry.split()
            res = load_result(name)
            sid = res.get("session_id")
            rc = open(os.path.join(BASE, "rc-%s.txt" % name)).read().strip() if os.path.exists(os.path.join(BASE, "rc-%s.txt" % name)) else "rc=?"
            print("=== %s | %s | is_error=%s num_turns=%s | result=%r" % (name, rc, res.get("is_error"), res.get("num_turns"), str(res.get("result"))[:140]))
            if not sid:
                print("    no session_id in out json")
                continue
            mains = glob.glob(os.path.join(PROJECTS, "*", sid + ".jsonl"))
            if not mains:
                print("    no main transcript for", sid)
                continue
            print("    main:", json.dumps(summarize(mains[0]), sort_keys=True))
            kids = sorted(glob.glob(os.path.join(os.path.dirname(mains[0]), sid, "**", "agent-*.jsonl"), recursive=True))
            for k in kids:
                print("    child:", json.dumps(summarize(k), sort_keys=True))


if __name__ == "__main__":
    main(sys.argv[1:])
